steps.run:
set +e
cargo test --locked -p maos-eval --test t3_escape_corpus --test t3_network_escape_executor --test t3_escape_workflow --release -- --nocapture 2>&1 | tee t3-escape.log
rc=${PIPESTATUS[0]}
set -e
python3 - <<'PY'
import collections, json, pathlib, re
root = pathlib.Path("crates/maos-eval/fixtures/t3-escape-corpus-v1")
expected = {json.loads(p.read_text())["scenario_id"] for p in root.glob("*/*.json")}
withdrawn = {row["id"] for row in json.loads((root / "methodology-attestation.json").read_text())["withdrawn"]}
declared = {json.loads(p.read_text())["scenario_id"] for p in pathlib.Path("crates/maos-eval/fixtures/t3-escape-corpus-v0").glob("*/*.json")}
log = pathlib.Path("t3-escape.log").read_text()
executed = re.findall(r"^T3-ESCAPE-EXECUTED (\S+) block_observed=true kind8=1 ", log, re.M)
counts = collections.Counter(executed)
if expected | withdrawn != declared or expected & withdrawn:
    raise SystemExit(f"T3 accounting failed: executable+withdrawn must equal the {len(declared)} declared v0 scenarios")
if set(counts) != expected or any(n != 1 for n in counts.values()):
    raise SystemExit(f"T3 accounting failed: executed={len(executed)}/{len(expected)} missing={sorted(expected-set(counts))} extra={sorted(set(counts)-expected)} duplicates={dict(counts)}")
if re.search(r"^SKIP[: ]|^T3-ESCAPE-UNEXECUTED ", log, re.M):
    raise SystemExit("T3 capable runner printed SKIP or an unexecuted scenario")
if "T3-NETWORK-MATRIX socket0600=refused socket0666=reachable" not in log:
    raise SystemExit("T3 socket custody matrix did not execute")
print(f"T3-ESCAPE-ACCOUNTING executed={len(counts)}/{len(expected)} withdrawn={len(withdrawn)} {sorted(withdrawn)} unexecuted=0")
PY
exit "$rc"

out="$(MAOS_ONE_SHOT=smoke-skill-7-4 cargo run -q -p maos-bin)"
echo "$out"
lines="$(printf '%s\n' "$out" | grep -c '"step"')"
test "$lines" -eq 4 || { echo "expected 4 JSON step lines, got $lines"; exit 1; }
printf '%s\n' "$out" | grep -q '"total":210' || { echo "LCAS total != 210"; exit 1; }

out="$(MAOS_ONE_SHOT=smoke-abi-7-5a cargo run -q -p maos-bin)"
echo "$out"
lines="$(printf '%s\n' "$out" | grep -c '"step"')"
test "$lines" -eq 5 || { echo "expected 5 JSON step lines, got $lines"; exit 1; }
printf '%s\n' "$out" | grep -q '"error":"ESubstrateTooOld"' || { echo "missing ESubstrateTooOld refusal"; exit 1; }
printf '%s\n' "$out" | grep -q '"error":"EAbiTooOld"' || { echo "missing EAbiTooOld refusal"; exit 1; }
printf '%s\n' "$out" | grep -q '"outcome":"in_sync"' || { echo "STABILITY.md not in sync"; exit 1; }

